// Hot batch 303: eighty and eighty-one-instruction functions no route reaches, written by hand from `tools.disasm`
// and verified by synthetic cases (script bridges and property accessors with string temporaries, object setup,
// name comparisons, a struct copy-out and a hundred-slot collector).
// No names: none has evidence.
#include "decomp_registry.hpp"
#include "gt/game/hot_common.hpp"
#include "guest_call.hpp"

